import{_ as a,H as i,f as e,i as n}from"./chunks/framework.BH2BK_3i.js";const c=JSON.parse('{"title":"29｜可观测性与排错：生产级系统的最后拼图","description":"","frontmatter":{},"headers":[{"level":2,"title":"先和Claude Code讨论可观测性方案","slug":"先和claude-code讨论可观测性方案","link":"#先和claude-code讨论可观测性方案","children":[]},{"level":2,"title":"结构化日志 + traceId","slug":"结构化日志-traceid","link":"#结构化日志-traceid","children":[]},{"level":2,"title":"指标埋点","slug":"指标埋点","link":"#指标埋点","children":[]},{"level":2,"title":"完善健康检查","slug":"完善健康检查","link":"#完善健康检查","children":[]},{"level":2,"title":"部署Prometheus","slug":"部署prometheus","link":"#部署prometheus","children":[]},{"level":2,"title":"生成Grafana Dashboard","slug":"生成grafana-dashboard","link":"#生成grafana-dashboard","children":[]},{"level":2,"title":"让Claude Code梳理告警策略","slug":"让claude-code梳理告警策略","link":"#让claude-code梳理告警策略","children":[]},{"level":2,"title":"验收","slug":"验收","link":"#验收","children":[]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"ClaudeCode企业级全链路开发实战/29｜可观测性与排错：生产级系统的最后拼图.md","filePath":"ClaudeCode企业级全链路开发实战/29｜可观测性与排错：生产级系统的最后拼图.md","lastUpdated":1779815375000}'),t={name:"ClaudeCode企业级全链路开发实战/29｜可观测性与排错：生产级系统的最后拼图.md"};function p(l,s,h,o,d,r){return i(),e("div",null,[...s[0]||(s[0]=[n(`<h1 id="_29-可观测性与排错-生产级系统的最后拼图" tabindex="-1">29｜可观测性与排错：生产级系统的最后拼图 <a class="header-anchor" href="#_29-可观测性与排错-生产级系统的最后拼图" aria-label="Permalink to &quot;29｜可观测性与排错：生产级系统的最后拼图&quot;">​</a></h1><p>你好，我是Robert。</p><p>Hify部署上去了，用户开始用了。然后你收到第一个反馈：“客服回复好慢”。</p><p>你打开服务器不知道慢在哪。是LLM调用慢？是数据库查询慢？是某个Provider触发了熔断？还是Redis连接耗尽了？你什么都看不到，因为系统是个黑盒。这也是我们在日常开发中经常遇到的问题。</p><p>这种问题在没有可观测性的系统里是最难受的，不是不能解决，是你连从哪里开始都不知道。只能靠猜，或者把每个可能的原因挨个排查，花上半天。</p><p>这一讲把它变透明。做完之后，同样的问题，你的处理方式是：看Grafana大盘LLM P95延迟最近一小时的趋势是什么样的。找到对应时间段的日志，用traceId过滤出这条请求的完整链路 <code>llm_call_done durationMs=3768 providerId=2</code>，LLM调用花了3.7秒，问题在Provider 2，不是Hify的问题。整个过程两分钟。</p><h2 id="先和claude-code讨论可观测性方案" tabindex="-1">先和Claude Code讨论可观测性方案 <a class="header-anchor" href="#先和claude-code讨论可观测性方案" aria-label="Permalink to &quot;先和Claude Code讨论可观测性方案&quot;">​</a></h2><p>不急着加代码。先用咨询模式搞清楚Hify需要做什么、不需要做什么。</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Hify 是一个 Spring Boot + Vue 的 AI 应用，模块化单体架构，部署在 K8s 上。</span></span>
<span class="line"><span>核心功能是 LLM 对话，依赖 MySQL、Redis、pgvector，调用外部 LLM API 和 MCP Server。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>我想加可观测性，帮我分析：</span></span>
<span class="line"><span>1. 应该做哪些，为什么</span></span>
<span class="line"><span>2. 哪些一期不需要做，理由是什么</span></span>
<span class="line"><span>3. 有没有什么需要提前考虑的架构决策</span></span>
<span class="line"><span></span></span>
<span class="line"><span>不要写代码，先给分析。</span></span></code></pre></div><p>Claude Code给出了系统性的分析，几个关键判断值得单独说。</p><p><strong>必须做的</strong>：结构化日志（每条日志带sessionId、agentId、providerId，格式用JSON）、Actuator健康端点细化到各依赖、LLM调用耗时和熔断指标（Resilience4j有Micrometer集成，加一个依赖就能暴露熔断器状态）、慢请求WARN日志（超过阈值打WARN，最低成本的性能感知）。</p><p><strong>一期不需要做的</strong>：分布式链路追踪（Hify是单体，一次请求不跨进程，Zipkin/Jaeger用不上）、前端监控（内部工具，投入产出比不够）、日志平台ELK（先落磁盘，用kubectl logs看，有聚合需求再接平台，不要一开始就引入ELK的运维复杂度）。</p><p>Claude Code提出了三个需要提前考虑的架构决策，这是这次分析最有价值的部分。</p><p><strong>决策一：Actuator端口隔离</strong>。Spring Boot支持把Actuator单独跑在另一个端口（如8081），业务API走8080对外，Actuator走8081只在集群内供Prometheus抓取。不提前规划，后续要改K8s Service和Nginx配置，代价较高。</p><p><strong>决策二：traceId现在就要放进MDC</strong>。虽然一期不做分布式追踪，但要提前在MDC里放traceId和sessionId。原因是将来接OpenTelemetry或SkyWalking时，traceId的字段名和注入位置需要对齐，提前占位可以平滑迁移，否则要改所有日志打点代码。</p><p><strong>决策三：日志字段规范要趁早定</strong>。日志字段一旦进了生产，改名代价极高，所有grep和告警规则都要跟着改。现在就定好字段名： <code>sessionId、agentId、providerId、modelName、action、durationMs、success、errorCode</code>，写进CLAUDE.md，所有LLM调用处统一遵守。</p><p>这三个决策你不一定自己想得到，但它们决定了后续扩展的成本。这就是咨询模式的价值，讨论清楚再动手，比做完了再回头改省力得多。这部分的回答，基本就涵盖了一个应用主要的可观测模块的组成了。</p><h2 id="结构化日志-traceid" tabindex="-1">结构化日志 + traceId <a class="header-anchor" href="#结构化日志-traceid" aria-label="Permalink to &quot;结构化日志 + traceId&quot;">​</a></h2><p>基于第一步的分析，日志这里要同时落地两件事： <strong>JSON格式 + traceId贯穿请求链路</strong>。</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮 Hify 配置结构化日志，同时引入 OpenTelemetry 生成 traceId。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>要求：</span></span>
<span class="line"><span>1. 日志格式是 JSON，包含 timestamp、level、traceId、thread、logger、message</span></span>
<span class="line"><span>2. 同一次请求的所有日志共享同一个 traceId，可以用 traceId 过滤出完整链路</span></span>
<span class="line"><span>3. traceId 通过 OpenTelemetry 生成，为后续链路追踪预留扩展点</span></span>
<span class="line"><span>4. 对话链路的关键节点要有日志：请求进入、LLM 调用开始/结束、工具调用、异常</span></span>
<span class="line"><span>5. 日志输出到 stdout，由 K8s 采集</span></span>
<span class="line"><span></span></span>
<span class="line"><span>不需要接 Jaeger 或 Zipkin，一期只用 traceId 串联日志。</span></span></code></pre></div><p>Claude Code没有直接生成代码，而是先读了项目中的相关文件，读完后给出了三个发现：</p><ol><li><p><code>RequestLogInterceptor</code> 已存在且有traceId逻辑，但新线程（llmExecutor）里MDC会丢失。</p></li><li><p><code>logback-spring.xml</code> 生产环境是手拼JSON字符串（有转义风险），输出到文件而非stdout。</p></li><li><p><code>ChatServiceImpl</code> 日志稀疏，缺少LLM调用开始/结束的结构化节点。</p></li></ol><p>三个问题都是提示词里没有说，Claude Code自己读代码发现的。这决定了它要做什么：引入logstash-logback-encoder、修复MDC跨线程丢失、重写logback配置、补结构化日志埋点、用OpenTelemetry API替换UUID生成traceId。</p><p>改动涉及是三个文件：</p><ol><li><p><strong>RequestLogInterceptor</strong>：用 <code>Span.current()</code> 获取traceId，当前无OTel Span时fallback到UUID 16位hex，保持格式一致。公开了MDC key常量（ <code>MDC_TRACE_ID</code>、 <code>MDC_SESSION_ID</code>），其他地方写MDC时用常量不用字符串字面量。</p></li><li><p><strong>MdcTaskWrapper（新建）</strong>：解决llmExecutor跨线程MDC丢失问题。父线程的MDC快照在提交任务时捕获，子线程执行前恢复，执行后清理。ChatServiceImpl里所有提交到llmExecutor的任务都用它包一层。</p></li><li><p><strong>logback-spring.xml（重写）</strong>：生产环境改用 <code>LogstashEncoder</code>，MDC字段（traceId、sessionId、agentId）自动提升为顶层JSON字段，不再手拼字符串。加异步Appender，避免I/O阻塞业务线程。开发环境保持可读格式。</p></li></ol><p>发完第一条提示词后，我又补了一条，把CLAUDE.md的字段规范加进约束。Claude Code回复说第一条已经实现，逐条对照了要求，发现只有 <code>providerId</code> 和 <code>success</code> 字段没有对齐，直接补了这两个字段进去没有重新生成所有文件，只改了缺失的部分。</p><p>做完后，一条完整的对话请求，日志链长这样：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;timestamp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2026-04-17T10:23:01.123Z&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;level&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;INFO&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;traceId&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;a3f1b2c4d5e6f708&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;sessionId&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;42&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;agentId&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;7&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;thread&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;llm-3&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;logger&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ChatServiceImpl&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;action=llm_call_start sessionId=42 agentId=7 providerId=2 modelName=gpt-4o tools=3&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;timestamp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2026-04-17T10:23:04.891Z&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;level&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;INFO&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;traceId&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;a3f1b2c4d5e6f708&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;sessionId&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;42&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;agentId&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;7&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;thread&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;llm-3&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;logger&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ChatServiceImpl&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;action=llm_call_done sessionId=42 agentId=7 providerId=2 modelName=gpt-4o durationMs=3768 success=true finishReason=stop tokens=245&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>用 <code>traceId=a3f1b2c4d5e6f708</code> 过滤，整条链路一目了然。回到开篇的问题：用户说“客服回复慢”，拿时间段搜日志，找到traceId，一看LLM调用花了3.7秒， <code>providerId=2</code>，问题在这个Provider端，不是Hify的问题。</p><p><strong>OpenTelemetry的扩展路径：</strong></p><p>一期 <code>Span.current()</code> 返回noop span，自动fallback到UUID。后续接入完整链路追踪时，只需在pom里加一行 <code>opentelemetry-spring-boot-starter</code> 依赖，traceId自动变成真实的OTel trace ID，所有日志和埋点代码零改动。这是第一步讨论时提到的架构决策在代码层面的落地。</p><h2 id="指标埋点" tabindex="-1">指标埋点 <a class="header-anchor" href="#指标埋点" aria-label="Permalink to &quot;指标埋点&quot;">​</a></h2><p>日志告诉你“某次请求发生了什么”；指标告诉你“系统整体状况如何”，过去一小时平均响应时间多少、LLM调用成功率多少、哪个Provider报错最多、熔断触发了几次。</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮 Hify 加 Prometheus 指标监控。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>需要埋点的位置：</span></span>
<span class="line"><span>1. 对话请求：请求总数（按 agentId 分组）、请求延迟分布</span></span>
<span class="line"><span>2. LLM 调用：调用总数（按 provider、model 分组）、调用延迟、成功/失败计数</span></span>
<span class="line"><span>3. 熔断器：各 Provider 熔断状态（CLOSED/OPEN/HALF_OPEN）</span></span>
<span class="line"><span>4. MCP 工具调用：调用次数、成功/失败</span></span>
<span class="line"><span></span></span>
<span class="line"><span>技术要求：</span></span>
<span class="line"><span>- 用 Spring Boot Actuator + Micrometer</span></span>
<span class="line"><span>- 指标通过 /actuator/prometheus 暴露</span></span>
<span class="line"><span>- 指标命名前缀统一用 hify_</span></span></code></pre></div><p>Claude Code先检查了pom和application.yml，确认没有任何Actuator/Micrometer依赖，然后读了 <code>CircuitBreakerService</code> 发现一个问题： <strong>熔断器用的是 <code>ConcurrentHashMap</code> 自建实例，不走Resilience4j的 <code>CircuitBreakerRegistry</code>，所以 Micrometer 自动集成无法采集到熔断器状态，需要手动注册 Gauge。</strong></p><p>这个细节你在提示词里没有提，Claude Code读代码后自己发现并处理了。</p><p>改动涉及五个文件：</p><ol><li><p><strong>pom文件</strong>：根pom加版本管理，hify-app引入 <code>spring-boot-starter-actuator</code> + <code>micrometer-registry-prometheus</code>，hify-common引入 <code>micrometer-core</code>（埋点用）。</p></li><li><p><strong>application.yml</strong>：Actuator独立跑在8081端口（和第一步讨论的架构决策一致），只暴露 <code>health</code> 和 <code>prometheus</code> 端点，不通过Nginx对外。</p></li><li><p><strong>HifyMetrics.java（新建）</strong>：统一管理所有指标定义，命名规范 <code>hify_{模块}_{动作}_{单位}</code>。熔断器状态用Gauge + <code>ConcurrentHashMap</code> 组合解决手动注册问题：状态变更时更新Map，Gauge读取Map的值，避免重复注册。</p></li><li><p><strong>CircuitBreakerService</strong>：熔断器状态变更时调用 <code>metrics.circuitBreakerState()</code>，把CLOSED/OPEN/HALF_OPEN编码为0/1/2写入Gauge。</p></li><li><p><strong>ChatServiceImplLLM</strong>：调用开始/结束、工具调用、对话完成各埋点，记录计数和耗时。</p></li></ol><p>做完后验证：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8081/actuator/prometheus</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hify_</span></span></code></pre></div><p>最终暴露的指标：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/973564/3bbd96e45c1a331da988c48d42357fa8.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/973564/3bbd96e45c1a331da988c48d42357fa8.png" alt=""></a></p><p>注意访问端口是8081，不是8080。Prometheus抓取配置也要指向8081：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">scrape_configs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">job_name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">hify</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    static_configs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">targets</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;hify-backend:8081&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><h2 id="完善健康检查" tabindex="-1">完善健康检查 <a class="header-anchor" href="#完善健康检查" aria-label="Permalink to &quot;完善健康检查&quot;">​</a></h2><p>28讲的 <code>/health</code> 只返回ok，现在完善成能反映各依赖的真实状态。</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>完善 Hify 的 /api/v1/health 接口。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>当前只返回 {&quot;code&quot;:0,&quot;data&quot;:&quot;ok&quot;}，需要改成：</span></span>
<span class="line"><span>- 检查 MySQL、Redis、pgvector 连通性</span></span>
<span class="line"><span>- 返回各依赖的状态和错误信息</span></span>
<span class="line"><span>- 整体状态：所有依赖 UP 才返回 UP，任何一个 DOWN 则整体 DOWN</span></span>
<span class="line"><span></span></span>
<span class="line"><span>格式参考：</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>  &quot;status&quot;: &quot;UP&quot;,</span></span>
<span class="line"><span>  &quot;components&quot;: {</span></span>
<span class="line"><span>    &quot;mysql&quot;: &quot;UP&quot;,</span></span>
<span class="line"><span>    &quot;redis&quot;: &quot;UP&quot;,</span></span>
<span class="line"><span>    &quot;pgvector&quot;: &quot;UP&quot;</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Claude Code先读了现有的HealthController、MockCacheConfig、KnowledgeServiceImpl和application.yml，发现三个需要处理的情况：</p><ol><li><p>mock profile没有Redis，直接检测会报错，需要跳过。</p></li><li><p>pgvector是外部PostgreSQL，当前application.yml里没有单独的连接配置，需要新增。</p></li><li><p>知识库模块目前是mock实现，pgvector配置为空时也要能正常启动。</p></li></ol><p>基于这些发现，Claude Code确定了设计方案：MySQL用已有DataSource执行 <code>SELECT 1</code>，Redis用 <code>Optional&amp;lt;RedisTemplate&gt;</code> 注入（没有Bean时显示 <code>skipped</code>），pgvector用独立JDBC URL（配置为空时显示 <code>skipped</code>）。DOWN时返回HTTP 503，而不是200，这是关键，K8s readinessProbe看的是HTTP状态码，只有收到非2xx才会把Pod标记为NotReady。</p><p>三种场景下的响应：</p><p>全部UP（HTTP 200）：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;status&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;UP&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;components&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;mysql&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;UP&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;redis&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;UP&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;pgvector&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;UP&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">​</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Redis故障（HTTP 503）：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;status&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;DOWN&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;components&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;mysql&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;UP&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;redis&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;status&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;DOWN&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;error&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Connection refused: localhost:6379&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">},</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;pgvector&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;UP&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">​</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>mock开发环境（HTTP 200，Redis和pgvector未配置）：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;status&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;UP&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;components&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;mysql&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;UP&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;redis&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;skipped&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;pgvector&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;skipped&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">​</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>skipped</code> 不算DOWN，开发环境下K8s探针不会误报。 <code>error</code> 字段只给运维看，不会通过Nginx暴露到公网。</p><p>为什么DOWN要返回503？28讲把 <code>/health</code> 配成了K8s的readinessProbe。readiness决定K8s要不要把流量导进这个Pod。如果MySQL挂了但接口还返回HTTP 200，K8s认为Pod健康，流量照常进来，所有查库的请求全报错。返回503，K8s发现readiness失败，把这个Pod从Service Endpoints里摘掉，流量自动切到其他正常Pod，用户不受影响。</p><h2 id="部署prometheus" tabindex="-1">部署Prometheus <a class="header-anchor" href="#部署prometheus" aria-label="Permalink to &quot;部署Prometheus&quot;">​</a></h2><p>部署Prometheus：</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我生成 Prometheus 的 K8s 部署文件。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>要求：</span></span>
<span class="line"><span>- 从 hify-backend 的 /actuator/prometheus 抓取指标，每 15 秒一次</span></span>
<span class="line"><span>- 数据持久化用 PVC</span></span>
<span class="line"><span>- Service 类型 ClusterIP，只在集群内访问</span></span></code></pre></div><p>Claude Code先读了application.yml确认端口，发现Actuator在8081而不是8080，提示词里写的端口是错的，Claude Code按实际配置写，不是按提示词写。</p><p>生成了四个文件：ConfigMap（抓取配置）、PVC（10Gi持久化存储）、Deployment、Service。</p><p>几个值得注意的设计：</p><ol><li><p>抓取地址是 <code>hify-backend:8081</code>，不是8080Actuator独立端口，不绕Nginx。</p></li><li><p><code>strategy: Recreate</code>：PVC的 <code>accessModes: ReadWriteOnce</code> 只允许单节点挂载。RollingUpdate会短暂存在两个Pod同时运行，新Pod挂载PVC会失败。Recreate先删旧Pod再起新Pod，单实例Prometheus的正确策略。</p></li><li><p>initContainer修正权限：Prometheus官方镜像以UID 65534（nobody）运行，PVC新建时目录权限是root，直接挂载会写入失败。initContainer提前 <code>chown</code>，避免启动报错。这个坑很隐蔽，你不一定想的到，Claude Code自动处理了。</p></li></ol><p>部署顺序：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apply</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy/k8s/prometheus-pvc.yml</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apply</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy/k8s/prometheus-configmap.yml</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apply</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy/k8s/prometheus-deployment.yml</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apply</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy/k8s/prometheus-service.yml</span></span></code></pre></div><p>结果验收，执行curl localhost:8081/actuator/prometheus即可看到下面的输出：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/973564/3a6b2588021d3d42274af981d0e89f5e.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/973564/3a6b2588021d3d42274af981d0e89f5e.png" alt=""></a></p><h2 id="生成grafana-dashboard" tabindex="-1">生成Grafana Dashboard <a class="header-anchor" href="#生成grafana-dashboard" aria-label="Permalink to &quot;生成Grafana Dashboard&quot;">​</a></h2><p>这是这一步的核心技巧。不需要自己手动在Grafana里拖拽配置面板，直接把指标列表给Claude Code，让它生成Dashboard JSON，导入就能用。</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我生成 Hify 的 Grafana Dashboard JSON。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Hify 暴露了以下指标：</span></span>
<span class="line"><span>- hify_chat_requests_total（label: agent_id）</span></span>
<span class="line"><span>- hify_chat_duration_ms（DistributionSummary，label: agent_id）</span></span>
<span class="line"><span>- hify_llm_calls_total（label: provider, model, success）</span></span>
<span class="line"><span>- hify_llm_duration_ms（DistributionSummary，label: provider, model）</span></span>
<span class="line"><span>- hify_circuit_breaker_state（label: provider，0=CLOSED 1=OPEN 2=HALF_OPEN）</span></span>
<span class="line"><span>- hify_mcp_tool_calls_total（label: tool, success）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Dashboard 需要包含以下面板：</span></span>
<span class="line"><span>1. 对话量（QPS 曲线，按 agent_id 分组）</span></span>
<span class="line"><span>2. 对话延迟（P50/P95/P99）</span></span>
<span class="line"><span>3. LLM 调用成功率（按 provider 分组）</span></span>
<span class="line"><span>4. LLM 调用延迟（P95，按 provider 分组）</span></span>
<span class="line"><span>5. 熔断器状态（各 Provider 当前状态）</span></span>
<span class="line"><span>6. MCP 工具调用成功率</span></span>
<span class="line"><span></span></span>
<span class="line"><span>输出完整的 Grafana Dashboard JSON，我直接导入使用。</span></span></code></pre></div><p>Claude Code生成了247行Dashboard JSON，但在输出之前先主动指出了一个问题：</p><blockquote><p>你的指标名和实际埋点有出入。根据HifyMetrics.java里的定义，实际指标名是 <code>hify_chat_duration_ms</code>（不是 <code>hify_chat_request_duration_seconds</code>），单位是毫秒，类型是DistributionSummary。以实际埋点的指标名生成Dashboard，否则面板会空白。</p></blockquote><p>然后在生成完成后又指出了第二个问题：</p><blockquote><p><code>HifyMetrics.java</code> 用的是DistributionSummary，Micrometer对DistributionSummary默认生成 <code>_count</code>、 <code>_sum</code>、 <code>_max</code>，不生成 <code>_bucket</code>。Dashboard里 <code>histogram_quantile()</code> 的查询会空白。如果要P95/P99精确分位数，需要在每个DistributionSummary.builder() 里加 <code>.publishPercentileHistogram(true)</code>，才能生成 <code>_bucket</code>。要不要现在改？</p></blockquote><p>确认后，Claude Code读了HifyMetrics.java，在所有DistributionSummary上加了这一行配置。</p><p>这两个问题你在提示词里都没提到，Claude Code一个是在执行前主动发现，一个是执行后自己检查发现。没有这两步，生成的Dashboard导入进去面板全是空白。</p><p>六个面板的设计：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/973564/2d685ef1ff7389b6c5ea4bd3edb569eb.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/973564/2d685ef1ff7389b6c5ea4bd3edb569eb.png" alt=""></a></p><p>导入方式：Grafana → Dashboards → Import → Upload JSON file → 选 <code>deploy/grafana-dashboard.json</code>。</p><h2 id="让claude-code梳理告警策略" tabindex="-1">让Claude Code梳理告警策略 <a class="header-anchor" href="#让claude-code梳理告警策略" aria-label="Permalink to &quot;让Claude Code梳理告警策略&quot;">​</a></h2><p>有了指标，下一步是告警。告警中又一个关键点是： <strong>不是所有异常都需要叫醒人，分级处理才能避免告警疲劳</strong>。</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>基于 Hify 当前暴露的指标，帮我梳理告警策略。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Hify 的业务背景：企业内部智能客服，工作时间使用，非 24 小时高可用场景。</span></span>
<span class="line"><span>用户规模：几十人并发。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>帮我整理：</span></span>
<span class="line"><span>1. 哪些指标需要告警</span></span>
<span class="line"><span>2. 每条告警的阈值建议和触发条件</span></span>
<span class="line"><span>3. 告警级别（P0 立即响应 / P1 30 分钟内 / P2 次日处理）</span></span>
<span class="line"><span>4. 理由</span></span>
<span class="line"><span></span></span>
<span class="line"><span>不要写 Grafana 配置，先给策略清单。</span></span></code></pre></div><p>Claude Code给出的清单分四个部分P0、P1、P2，以及不建议告警的指标。</p><ul><li>P0：立即响应（服务不可用） <ul><li><p>后端scrape失败： <code>up{job=&quot;hify-backend&quot;} == 0</code> 持续1分钟。后端进程挂了或网络断了，所有用户无法使用。</p></li><li><p>health接口返回503：持续2分钟。MySQL断开后所有对话写入失败，服务完全不可用。</p></li><li><p>所有provider熔断器全部OPEN： <code>min(hify_circuit_breaker_state) == 1</code> 持续5分钟。所有LLM provider都熔断意味着完全无法对话。</p></li></ul></li><li>P1：30分钟内响应（功能降级） <ul><li><p>LLM调用错误率 &gt; 30%，持续5分钟：每3次对话就有1次失败，用户体验已明显受损；低于这个值可能是偶发网络抖动。</p></li><li><p>单个provider熔断器持续OPEN超过10分钟：10分钟是给provider自动恢复的宽限时间，超过说明需要人工介入。</p></li><li><p>对话P95延迟 &gt; 30秒，持续10分钟：LLM正常响应5-15s，30s是明显异常，不是LLM本身慢而是系统级问题。</p></li><li><p>Redis DOWN持续3分钟：Redis断开后上下文缓存失效，每次对话回落到MySQL加载历史，性能下降但不完全不可用；3分钟给Redis自动重连的时间。</p></li></ul></li><li>P2：次日处理（潜在风险） <ul><li><p>LLM P95延迟 &gt; 15秒，持续30分钟：15s慢但在用户接受范围内，可能是provider侧负载高，次日评估是否要切换模型。</p></li><li><p>MCP工具调用失败率 &gt; 20%，持续15分钟：工具失败不影响基础对话，但持续失败说明外部系统有问题。</p></li><li><p>工作时间对话量骤降80%，持续20分钟：工作时间（9-18点）对话量骤降往往是前端不可达或Nginx挂了，后端看起来正常，容易漏报。</p></li></ul></li><li>不建议告警的指标： <ul><li><p>单次LLM调用延迟（LLM本身就慢，偶发20s属正常）。</p></li><li><p>MCP工具调用次数（业务量指标，不代表故障）。</p></li><li><p>非工作时间的任何P1/P2（内部工具，夜间无人使用无需on-call）。</p></li><li><p>熔断器HALF_OPEN状态（是正常恢复流程，不需要打扰人）。</p></li></ul></li></ul><p><strong>汇总表如下</strong>：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/973564/106deb84a4a3f9b8f7633602b7a3d1da.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/973564/106deb84a4a3f9b8f7633602b7a3d1da.png" alt=""></a></p><p>这份清单有两点值得注意。</p><p>第一，Claude Code一开始就分析了“业务背景对告警的影响”内部工具、工作时间使用、几十人并发，这三个条件决定了阈值要比C端产品宽松，非工作时间的P1/P2不需要on-call。阈值是根据业务场景定的，不是套通用标准。</p><p>第二，“不建议告警”这部分和正面清单同样重要，告警太多会产生疲劳，让人忽略真正重要的告警。HALF_OPEN状态是一个典型例子，看起来像异常，实际上是熔断器正常恢复流程，加了告警只会让人误判。</p><p>策略确认后，让Claude Code生成对应的Grafana Alert规则JSON，导入配置即可。</p><h2 id="验收" tabindex="-1">验收 <a class="header-anchor" href="#验收" aria-label="Permalink to &quot;验收&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 部署 Prometheus 和 Grafana</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apply</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy/k8s/prometheus-pvc.yml</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apply</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy/k8s/prometheus-configmap.yml</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apply</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy/k8s/prometheus-deployment.yml</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apply</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy/k8s/prometheus-service.yml</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apply</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy/k8s/grafana.yaml</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pods</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hify</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 确认都在 Running</span></span></code></pre></div><p>产生真实数据：和Hify对话几轮，触发RAG检索，绑定MCP工具查询订单。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/973564/061f9441b8b89d49774c7eb1bbfcd536.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/973564/061f9441b8b89d49774c7eb1bbfcd536.png" alt=""></a></p><ul><li><p>打开Grafana大盘（节点IP:30030），确认</p></li><li><p>对话量QPS曲线有数据</p></li><li><p>对话延迟P50/P95/P99有分布</p></li><li><p>LLM调用成功率按provider分组显示</p></li><li><p>熔断器状态表格显示CLOSED（绿色）</p></li></ul><p>验证日志链：找一条刚才的对话，搜它的traceId</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hify</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy/hify-backend</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;traceId=&amp;lt;你的traceId&amp;gt;&quot;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 应该看到从 http_request → llm_call_start → llm_call_done → chat_stream_done</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 完整链路的所有日志，durationMs 告诉你每一步的耗时</span></span></code></pre></div><p>模拟依赖故障，验证健康检查 + K8s自动摘流量：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 临时断开 Redis（在 Redis 侧 kill 连接或停服务）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://hify-backend:8080/api/v1/health</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># {&quot;status&quot;:&quot;DOWN&quot;,&quot;components&quot;:{&quot;mysql&quot;:&quot;UP&quot;,&quot;redis&quot;:{&quot;status&quot;:&quot;DOWN&quot;,&quot;error&quot;:&quot;Connection refused&quot;},&quot;pgvector&quot;:&quot;UP&quot;}​}</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pods</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hify</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># hify-backend-xxx   0/1   Running   0   10m   ← 0/1 表示 NotReady，K8s 已摘掉流量</span></span></code></pre></div><p>Redis恢复后，健康检查重新返回UP，Pod变回1/1 Ready，流量自动恢复。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>这一讲做完，“客服回复好慢”这个问题有了完整的排查路径。</p><p><strong>traceId定位单次请求</strong>：拿时间段搜日志，找到traceId， <code>llm_call_done durationMs=3768</code> 告诉你LLM调用花了3.7秒， <code>providerId=2</code> 告诉你是哪个Provider的问题。</p><p><strong>Grafana大盘看趋势</strong>：不是偶发就是系统性问题，LLM P95延迟面板一眼看出。Dashboard JSON是Claude Code生成的，不需要手动拖拽配置，而且Claude Code在生成前主动发现了指标名不对，生成后发现DistributionSummary缺 <code>_bucket</code> 会导致面板空白，这两步你不一定想的到。</p><p><strong>健康检查自动摘流量</strong>：MySQL或Redis故障时，readinessProbe检测到503，K8s自动把Pod从负载均衡里摘掉，用户请求不会打到故障实例。</p><p><strong>分级告警不吵人</strong>：10条告警，3条P0立即响应，其余按级别处理。不建议告警的清单和正面清单同样重要，Claude Code是结合Hify的业务背景（内部工具、工作时间使用）给出的阈值，不是套通用标准。</p><p>整个过程几个反复出现的模式值得记住：Claude Code先读代码再动手，提示词里没说的问题它自己发现；执行后主动做自检，发现DistributionSummary的问题是执行后检查到的；端口写错了按实际配置生成，不是按提示词盲目执行。这些加在一起，和“告诉AI写什么就写什么”是两种完全不同的工作方式。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><ol><li><p>当前日志输出到stdout，由K8s采集，用 <code>kubectl logs</code> 看。如果要加按traceId全文搜索的能力，需要引入日志平台。让Claude Code对比Loki和EFK两个方案，结合Hify的规模给出建议重点，问它运维复杂度和资源消耗的差异。</p></li><li><p>告警策略清单确认了，下一步是把它变成Grafana Alert规则。P0-3 “所有provider熔断器全部OPEN” 对应的PromQL是 <code>min(hify_circuit_breaker_state) == 1</code>，让Claude Code帮你生成这条告警的Grafana Alert JSON，测试能否正确触发。</p></li><li><p>OpenTelemetry现在只用了traceId串联日志， <code>Span.current()</code> 返回noop。如果要开启完整链路追踪每个LLM调用，每次数据库查询都记录成Span，发到Jaeger可视化需要做哪些改动？让Claude Code评估改动范围，重点看是否需要修改业务代码。</p></li></ol><p>期待你的分享！如果今天的课程让你有所收获，也欢迎转发给有需要的朋友，邀请他来一起学习，我们下节课再见！</p>`,113)])])}const u=a(t,[["render",p]]);export{c as __pageData,u as default};
